	/** No new effectful/unknown observer enters the alias unit's pinned template. */
	private static boolean plainObservers(TupleExpr expression, Projection projection) {
		TupleExpr node = expression;
		while (node != projection) {
			Class<?> type = node.getClass();
			if (type == Order.class) {
				for (var key : ((Order) node).getElements())
					if (key.getExpr().getClass() != Var.class || ((Var) key.getExpr()).hasValue())
						return false;
			} else if (type != QueryRoot.class && type != Distinct.class && type != Reduced.class
					&& type != Slice.class)
				return false;
			node = ((org.eclipse.rdf4j.query.algebra.UnaryTupleOperator) node).getArg();
		}
		return true;
	}

	private record PhysicalVisit(SlotPlan node, boolean after) {
	}

	/** Private strengthened assurance facts: no general SlotPlan cardinality/domain claim is changed. */
	private static final class PhysicalProof {
		final IdentityHashMap<SlotPlan, Long> possible = new IdentityHashMap<>();
		final IdentityHashMap<SlotPlan, Long> assured = new IdentityHashMap<>();

		static PhysicalProof create(SlotPlan root, NativeSlotLayout layout, BodyProof logical) {
			PhysicalProof proof = new PhysicalProof();
			Map<List<Alias>, Integer> recipes = new HashMap<>();
			IdentityHashMap<SlotPlan, Boolean> entered = new IdentityHashMap<>();
			ArrayDeque<PhysicalVisit> pending = new ArrayDeque<>();
			pending.push(new PhysicalVisit(root, false));
			int tick = 0;
			while (!pending.isEmpty()) {
				NativeCancellationToken.checkCurrent();
				LmdbNativeProbeDeadline.poll(++tick);
				PhysicalVisit visit = pending.pop();
				SlotPlan node = visit.node;
				if (proof.possible.containsKey(node))
					continue;
				if (!visit.after) {
					if (entered.put(node, Boolean.TRUE) != null)
						return null;
					pending.push(new PhysicalVisit(node, true));
					if (node instanceof ExtensionPlan extension) {
						pending.push(new PhysicalVisit(extension.arg, false));
					} else if (node instanceof MultiJoinPlan multi) {
						for (SlotPlan child : multi.children)
							pending.push(new PhysicalVisit(child, false));
					} else if (node instanceof JoinPlan join) {
						pending.push(new PhysicalVisit(join.right, false));
						pending.push(new PhysicalVisit(join.left, false));
					} else if (node instanceof LeftJoinPlan optional) {
						pending.push(new PhysicalVisit(optional.right, false));
						pending.push(new PhysicalVisit(optional.left, false));
					} else if (node instanceof UnionPlan union) {
						pending.push(new PhysicalVisit(union.right, false));
						pending.push(new PhysicalVisit(union.left, false));
					} else if (!(node instanceof PatternPlan) && node != EmptyPlan.INSTANCE
							&& node != SingletonPlan.INSTANCE)
						return null;
					continue;
				}
				long possible;
				if (node instanceof ExtensionPlan extension) {
					possible = proof.possible.get(extension.arg);
					long assured = proof.assured.get(extension.arg);
					java.util.ArrayList<Alias> copies = new java.util.ArrayList<>();
					for (CopyBinding copy : extension.copies) {
						if (copy.sourceSlot < 0 || copy.sourceSlot >= layout.slotNames().length
								|| copy.targetSlot < 0 || copy.targetSlot >= layout.slotNames().length
								|| !copy.assignment || copy.setNullOnError || copy.termChecked
								|| !copy.encounterOrderReplaySafe || copy.computed != null
								|| copy.computedValue != null || copy.semanticValue != null
								|| copy.constant != NativeLmdbQuerySource.UNKNOWN_ID
								|| (possible & 1L << copy.targetSlot) != 0L
								|| (assured & 1L << copy.sourceSlot) == 0L)
							return null;
						copies.add(new Alias(layout.slotName(copy.sourceSlot), layout.slotName(copy.targetSlot)));
						possible |= 1L << copy.targetSlot;
						assured |= 1L << copy.targetSlot;
					}
					if (copies.isEmpty())
						return null;
					recipes.merge(List.copyOf(copies), 1, Integer::sum);
					proof.assured.put(node, assured);
				} else if (node instanceof MultiJoinPlan multi) {
					possible = 0L;
					for (SlotPlan child : multi.children)
						possible |= proof.possible.get(child);
				} else if (node instanceof JoinPlan join) {
					possible = proof.possible.get(join.left) | proof.possible.get(join.right);
				} else if (node instanceof LeftJoinPlan optional) {
					possible = proof.possible.get(optional.left) | proof.possible.get(optional.right);
				} else if (node instanceof UnionPlan union) {
					possible = proof.possible.get(union.left) | proof.possible.get(union.right);
				} else {
					possible = node instanceof PatternPlan ? node.producedMask() : 0L;
				}
				proof.possible.put(node, possible);
				// Every child's private fact is already present, including proved alias targets; this is O(outdegree).
				if (!(node instanceof ExtensionPlan))
					SlotPlan.assuredMask(node, proof.assured);
			}
			return recipes.equals(logical.recipes) ? proof : null;
		}
	}

